@font-face { font-family: Fredoka; src: url("/demo/fonts/Fredoka-Variable.ttf") format("truetype"); font-weight: 300 700; font-display: swap; }@font-face { font-family: Nunito; src: url("/demo/fonts/Nunito-Variable.ttf") format("truetype"); font-weight: 200 1000; font-display: swap; }:root { --background: #fff6ea; --foreground: #2b2118; --card: #ffffff; --card-foreground: #2b2118; --popover: #ffffff; --popover-foreground: #2b2118; --primary: #ff5c8a; --primary-foreground: #2b2118; --secondary: #fdecd4; --secondary-foreground: #2b2118; --muted: #f6ead9; --muted-foreground: #5c4f43; --accent: #fdecd4; --accent-foreground: #2b2118; --destructive: #c53030; --border: #e6d8c4; --input: #e6d8c4; --ring: #2a78d6; --chart-1: #2a78d6; --chart-2: #eb6834; --chart-3: #8a8780; --chart-4: #1f8a4c; --chart-5: #a8660b; --radius: 0.875rem; --line: #2b2118; --shadow-color: #2b2118; --faint-foreground: #75685b; --highlight: #ffd45c; --highlight-foreground: #2b2118; --human: #2a78d6; --human-soft: #dcebfc; --human-foreground: #1c5cab; --agent: #eb6834; --agent-soft: #fde2d4; --agent-foreground: #a33d15; --unsure: #8a8780; --unsure-soft: #ece7df; --unsure-foreground: #5e5b55; --ok: #1f8a4c; --ok-soft: #dcf3e4; --warn: #a8660b; --warn-soft: #fdf0d3; --cake-sponge: #ffd99e; --cake-jam: #ff6f91; --cake-cream: #fff3df; --cake-frosting: #ff8fb1; --cake-cherry: #e5383b; --cake-cheek: #ff9fb8; --cake-shine: #ffffff; --cake-outline: #2b2118; --cake-line: #2b2118; --avatar-1: #5fcf95; --avatar-2: #a48cf2; --avatar-3: #f27fb3; --avatar-4: #a9cf45; --avatar-5: #d77fdc; --avatar-6: #5cc8cf; --font-sans: "Nunito", ui-rounded, system-ui, -apple-system, "Segoe UI", sans-serif; --font-heading: "Fredoka", "Nunito", ui-rounded, system-ui, sans-serif; --font-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace; }@media (prefers-color-scheme: dark) {
  :root { --background: #1b1713; --foreground: #f6eee3; --card: #262019; --card-foreground: #f6eee3; --popover: #2d261e; --popover-foreground: #f6eee3; --primary: #ff6f98; --primary-foreground: #1b1713; --secondary: #2d261e; --secondary-foreground: #f6eee3; --muted: #17130f; --muted-foreground: #cfc2b1; --accent: #352c23; --accent-foreground: #f6eee3; --destructive: #f07070; --border: #3a3129; --input: #3a3129; --ring: #6ea8f0; --chart-1: #3987e5; --chart-2: #e0682f; --chart-3: #8f8a82; --chart-4: #4cc27f; --chart-5: #e3a63c; --line: #5a4d40; --shadow-color: #0b0806; --faint-foreground: #a99a88; --highlight: #7a5c12; --highlight-foreground: #f6eee3; --human: #3987e5; --human-soft: #1c3150; --human-foreground: #9cc4f5; --agent: #e0682f; --agent-soft: #4a2617; --agent-foreground: #f5a982; --unsure: #8f8a82; --unsure-soft: #36312b; --unsure-foreground: #cdc7bd; --ok: #4cc27f; --ok-soft: #173525; --warn: #e3a63c; --warn-soft: #3b2c10; --cake-sponge: #f2c27e; --cake-jam: #f0597e; --cake-cream: #f7e6cc; --cake-frosting: #f67ea3; --cake-cherry: #e5484b; --cake-cheek: #f58aa7; --cake-shine: #fff6ea; --cake-outline: #120e0a; --cake-line: #d9cab6; --avatar-1: #8fdcb4; --avatar-2: #c3b1ff; --avatar-3: #ffa6c9; --avatar-4: #d6e27a; --avatar-5: #e8a6ea; --avatar-6: #94dde2; }
}* { box-sizing: border-box; }:root { color-scheme: light dark; }body { margin: 0px; background: var(--background); color: var(--foreground); font-family: var(--font-sans); font-weight: 500; line-height: 1.5; -webkit-font-smoothing: antialiased; overflow-x: hidden; }h1, h2, h3 { font-family: var(--font-heading); font-weight: 600; line-height: 1.15; margin: 0px 0px 0.75rem; }h1 { font-size: 2.25rem; }h2 { font-size: 1.5rem; }h3 { font-size: 1.125rem; margin: 0px; }p { margin: 0px 0px 0.75rem; }a { color: inherit; text-decoration: underline 2px; text-underline-offset: 4px; }a:hover { text-decoration-color: var(--primary); }.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); }.mut { color: var(--muted-foreground); }a:focus-visible, summary:focus-visible { outline: 3px solid color-mix(in srgb, var(--ring) 50%, transparent); outline-offset: 2px; border-radius: 0.25rem; }.demo-note { background: var(--warn-soft); color: var(--foreground); border-bottom: 2px solid var(--line); text-align: center; font-size: 0.875rem; padding: 0.375rem 1rem; }.top { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem 1rem; max-width: 72rem; margin: 0px auto; padding: 0.75rem 1rem; }.brand { font-family: var(--font-heading); font-weight: 700; font-size: 1.5rem; text-decoration: none; }.search { display: flex; align-items: center; gap: 0.5rem; margin-left: auto; flex: 1 1 16rem; max-width: 28rem; }.search input { flex: 1 1 0%; }.cartlink { font-weight: 800; }main { max-width: 72rem; margin: 0px auto; padding: 1rem 1rem 4rem; }.foot { max-width: 72rem; margin: 0px auto; text-align: center; color: var(--faint-foreground); font-size: 0.875rem; padding: 1rem; }input, select, button { font: inherit; color: inherit; }input[type="search"], input[type="text"], input[type="email"], input[type="number"], select { width: 100%; min-width: 0px; height: 2.5rem; padding: 0.25rem 0.75rem; font-size: 0.875rem; color: var(--foreground); background: var(--card); border: 2px solid var(--line); border-radius: var(--radius); }select { border-color: var(--border); border-radius: 999px; padding-left: 0.875rem; font-weight: 700; }input::placeholder { color: var(--muted-foreground); }input:focus-visible, select:focus-visible { border-color: var(--ring); outline: 3px solid color-mix(in srgb, var(--ring) 50%, transparent); outline-offset: 0px; }input[type="radio"], input[type="checkbox"] { width: 1rem; height: 1rem; margin: 0px; accent-color: var(--foreground); }button, .btn { display: inline-flex; align-items: center; justify-content: center; height: 2.25rem; padding: 0px 0.875rem; font-size: 0.875rem; font-weight: 800; white-space: nowrap; text-decoration: none; color: var(--primary-foreground); background: var(--primary); border: 2px solid var(--line); border-radius: var(--radius); box-shadow: 2px 2px 0 var(--shadow-color); cursor: pointer; transition: transform 150ms, box-shadow 150ms; }button:hover, .btn:hover { transform: translate(-1px, -1px); box-shadow: 4px 4px 0 var(--shadow-color); }button:active, .btn:active { transform: translate(1px, 1px); box-shadow: none; }button:focus-visible, .btn:focus-visible { border-color: var(--ring); outline: 3px solid color-mix(in srgb, var(--ring) 50%, transparent); outline-offset: 0px; }button:disabled { opacity: 0.5; pointer-events: none; }button.ghost { color: var(--foreground); background: var(--card); }.filters { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 0.75rem 1rem; margin: 0px 0px 1.5rem; }.filters label { display: block; margin-bottom: 0.375rem; font-size: 0.875rem; font-weight: 700; color: var(--muted-foreground); }.filters select { width: auto; min-width: 11rem; }.filters > div:last-child { padding-bottom: 0.5rem; }.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr)); gap: 1.25rem; margin-bottom: 2rem; }.card { display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; background: var(--card); color: var(--card-foreground); border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.8); box-shadow: 4px 4px 0 var(--shadow-color); }.card > a { line-height: 0; }.card .body { display: flex; flex-direction: column; gap: 0.25rem; flex: 1 1 0%; padding: 0px 0.25rem 0.25rem; }.card h3 a { text-decoration: none; }.card h3 a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: var(--primary); }.card .mut { font-size: 0.875rem; }.card a.more { margin-top: auto; padding-top: 0.5rem; align-self: flex-start; font-size: 0.875rem; font-weight: 800; }.price { font-weight: 800; }.swatch { display: block; width: 100%; aspect-ratio: 4 / 3; border-radius: var(--radius); }.swatch rect { fill: var(--muted); }.swatch path { stroke: var(--line); stroke-width: 3; stroke-linejoin: round; }.pager { display: flex; flex-wrap: wrap; gap: 0.5rem; align-items: center; justify-content: center; margin: 1.5rem 0px 0.5rem; }.pager a, .pager span { display: inline-flex; align-items: center; justify-content: center; min-width: 2.25rem; height: 2.25rem; padding: 0px 0.75rem; font-size: 0.875rem; font-weight: 800; text-decoration: none; background: var(--card); border: 2px solid var(--line); border-radius: var(--radius); }.pager span.cur { color: var(--background); background: var(--foreground); }.product { display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr); gap: 2rem; align-items: start; }@media (max-width: 45rem) {
  .product { grid-template-columns: 1fr; }
}.product .img { padding: 0.75rem; line-height: 0; background: var(--card); border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.8); box-shadow: 4px 4px 0 var(--shadow-color); }.opts { display: flex; flex-direction: column; gap: 1rem; margin: 1.25rem 0px; }.colors { display: flex; flex-wrap: wrap; gap: 0.5rem; }.colors label { display: inline-flex; align-items: center; gap: 0.5rem; height: 2.25rem; padding: 0px 0.875rem; font-size: 0.875rem; font-weight: 700; background: var(--card); border: 2px solid var(--border); border-radius: 999px; cursor: pointer; }.colors label:has(input:checked) { background: var(--secondary); border-color: var(--line); box-shadow: 2px 2px 0 var(--shadow-color); }.colors i { display: inline-block; width: 1rem; height: 1rem; border: 2px solid var(--line); border-radius: 999px; }.row { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: flex-end; }.row > div { flex: 1 1 9rem; }.row label { display: block; margin-bottom: 0.375rem; font-weight: 700; }.msg { min-height: 1.5rem; margin: 0.5rem 0px; font-size: 0.875rem; font-weight: 700; }.msg.ok:not(:empty), .msg.bad:not(:empty) { padding: 0.625rem 0.875rem; border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.4); }.msg.ok:not(:empty) { color: var(--foreground); background: var(--ok-soft); }.msg.bad { color: var(--destructive); }.msg.bad:not(:empty) { background: var(--card); }details { margin-top: 1rem; }summary { cursor: pointer; font-weight: 800; }.reviews { margin-top: 2.5rem; }.reviews + section { margin-top: 2.5rem; }.review { padding: 0.75rem 0px; border-top: 2px solid var(--border); }.review p { margin: 0.25rem 0px 0px; }.stars { color: var(--warn); letter-spacing: 0.1em; }.tablewrap { overflow-x: auto; margin: 0.5rem 0px; background: var(--card); border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.8); box-shadow: 4px 4px 0 var(--shadow-color); }table { width: 100%; border-collapse: collapse; font-size: 0.875rem; }th { height: 2.5rem; padding: 0px 0.75rem; text-align: left; font-weight: 700; white-space: nowrap; background: var(--muted); }td { padding: 0.5rem 0.75rem; vertical-align: middle; border-top: 1px solid var(--border); }.cartrow input { width: 4.5rem; height: 2.25rem; }.cartrow button { height: 1.75rem; padding: 0px 0.625rem; font-size: 0.8rem; }.totals { max-width: 22.5rem; margin: 1rem 0px 0px auto; }.totals div { display: flex; justify-content: space-between; gap: 1rem; padding: 0.25rem 0px; }.totals .grand { margin-top: 0.25rem; padding-top: 0.5rem; font-size: 1.125rem; font-weight: 800; border-top: 2px solid var(--line); }form.checkout { display: grid; grid-template-columns: minmax(0px, 1.4fr) minmax(0px, 1fr); gap: 2rem; align-items: start; }@media (max-width: 45rem) {
  form.checkout { grid-template-columns: 1fr; }
}fieldset { min-width: 0px; margin: 0px 0px 1.25rem; padding: 1rem 1.25rem 1.25rem; background: var(--card); border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.8); }legend { float: left; width: 100%; padding: 0px; font-family: var(--font-heading); font-size: 1.125rem; font-weight: 600; }legend + * { clear: both; }fieldset label { display: block; margin: 0.75rem 0px 0.375rem; font-size: 0.875rem; font-weight: 700; }label.inline { display: flex; align-items: center; gap: 0.5rem; margin: 0.5rem 0px; font-size: 0.875rem; font-weight: 600; cursor: pointer; }fieldset p.mut { padding-top: 0.5rem; }.summary { padding: 1.25rem; background: var(--card); border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.8); box-shadow: 4px 4px 0 var(--shadow-color); }.done { max-width: 36rem; margin: 1rem auto; padding: 2.5rem 1.5rem; text-align: center; background: var(--card); border: 2px solid var(--line); border-radius: calc(var(--radius) * 1.8); box-shadow: 4px 4px 0 var(--shadow-color); }.done .code { display: inline-block; margin: 0px 0px 1rem; padding: 0.25rem 1rem; font-family: var(--font-heading); font-size: 2rem; font-weight: 700; letter-spacing: 0.05em; color: var(--highlight-foreground); background: var(--highlight); border: 2px solid var(--line); border-radius: var(--radius); }@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
